<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $previous = strtotime( '-1 month', strtotime( $first ) ); $next = strtotime( '+1 month', strtotime( $first ) ); ?>
<div class="wrap rr-admin-wrap" id="rr-admin-calendar" data-year="<?php echo absint( $year ); ?>" data-month="<?php echo absint( $month ); ?>">
	<h1><?php esc_html_e( 'Reservation Calendar', 'restaurant-reservations' ); ?></h1>
	<div class="rr-calendar-nav"><a class="button rr-calendar-previous" href="<?php echo esc_url( add_query_arg( array( 'page' => 'rr-calendar', 'rr_year' => gmdate( 'Y', $previous ), 'rr_month' => gmdate( 'n', $previous ) ), admin_url( 'admin.php' ) ) ); ?>"><?php esc_html_e( 'Previous', 'restaurant-reservations' ); ?></a><h2><?php echo esc_html( wp_date( 'F Y', strtotime( $first ) ) ); ?></h2><a class="button rr-calendar-next" href="<?php echo esc_url( add_query_arg( array( 'page' => 'rr-calendar', 'rr_year' => gmdate( 'Y', $next ), 'rr_month' => gmdate( 'n', $next ) ), admin_url( 'admin.php' ) ) ); ?>"><?php esc_html_e( 'Next', 'restaurant-reservations' ); ?></a></div>
	<div class="rr-admin-calendar-grid"><?php foreach ( array( __( 'Sun', 'restaurant-reservations' ), __( 'Mon', 'restaurant-reservations' ), __( 'Tue', 'restaurant-reservations' ), __( 'Wed', 'restaurant-reservations' ), __( 'Thu', 'restaurant-reservations' ), __( 'Fri', 'restaurant-reservations' ), __( 'Sat', 'restaurant-reservations' ) ) as $weekday ) : ?><strong><?php echo esc_html( $weekday ); ?></strong><?php endforeach; ?><?php for ( $blank = 0; $blank < (int) gmdate( 'w', strtotime( $first ) ); $blank++ ) : ?><span class="rr-calendar-empty"></span><?php endfor; ?><?php foreach ( $counts as $date => $count ) : ?><a class="rr-calendar-day" href="<?php echo esc_url( add_query_arg( array( 'page' => 'rr-reservations', 'start_date' => $date, 'end_date' => $date ), admin_url( 'admin.php' ) ) ); ?>"><b><?php echo absint( gmdate( 'j', strtotime( $date ) ) ); ?></b><span><?php echo esc_html( sprintf( _n( '%d reservation', '%d reservations', $count, 'restaurant-reservations' ), $count ) ); ?></span></a><?php endforeach; ?></div>
</div>
